SET @existing_batch = (SELECT COUNT(*) FROM Accounts a JOIN sd_users s ON a.username=s.username OR a.email=s.email);
SET @seed_apply = IF(@seed_authorized=1 AND @seed_lock=1 AND @existing_batch=0,1,0);
SELECT g.profileId FROM GymUsers g JOIN Accounts a ON a.accountId=g.accountId WHERE a.accountId=28 OR LEFT(a.username,12)='gym_demo_v2_' FOR UPDATE;

INSERT INTO sd_guard (message, ok) SELECT 'Batch must be entirely absent or all 30 exact seed account identities present', IF((@existing_batch=0 OR (@existing_batch=30 AND (SELECT COUNT(*) FROM sd_users s JOIN Accounts a ON a.username=s.username AND a.email=s.email AND a.createdAt=s.createdAt AND a.role='GYM_USER')=30)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Target identity and ACTIVE membership must still match reviewed data', IF((@seed_apply=0 OR (SELECT COUNT(*) FROM Accounts a JOIN GymUsers g ON g.accountId=a.accountId JOIN GymUserWorkoutPlans uw ON uw.profileId=g.profileId JOIN WorkoutPlans p ON p.planId=uw.planId WHERE a.accountId=28 AND a.username='gym_minh' AND a.email='minh@example.test' AND a.status='ACTIVE' AND g.level='BEGINNER' AND g.goal='Sức bền' AND g.sessionsPerWeek=3 AND uw.status='ACTIVE' AND p.title='Nguyễn Hoàng Minh - minh_current' AND uw.joinedAt='2026-08-25 00:00:00')=1),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Manifest is entirely in the past', IF(((SELECT MAX(endTime) FROM sd_sessions)<=NOW() AND (SELECT MAX(recordedAt) FROM sd_metrics)<=NOW() AND (SELECT MAX(createdAt) FROM sd_users)<=NOW()),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: accounts. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=23 AND signature='0f88e7f05efc9f6862d6caddcc879d5e3956b874bbdd67f13073756be0a3d1ad' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`accountId`,`username`,`email`,`role`,`status`,`createdAt`) AS CHAR),256) ORDER BY `accountId`,`username`,`email`,`role`,`status`,`createdAt` SEPARATOR ''),''),256) signature FROM `accounts`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: gymusers. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=22 AND signature='0ff416c48fd568dbc65933b7e830184f963fcf9df85d4f6ef19c3f14718c78fd' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`profileId`,`accountId`,`fullName`,`gender`,`level`,`goal`,`sessionsPerWeek`,`status`) AS CHAR),256) ORDER BY `profileId`,`accountId`,`fullName`,`gender`,`level`,`goal`,`sessionsPerWeek`,`status` SEPARATOR ''),''),256) signature FROM `gymusers`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: workoutplans. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=18 AND signature='0f87f81eb0b5209b8da15959c8e9534a9e989b2b35038af8f9be9e409dc630e7' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`planId`,`title`,`description`,`creatorId`,`isTemplate`,`level`,`durationWeeks`,`createdAt`) AS CHAR),256) ORDER BY `planId`,`title`,`description`,`creatorId`,`isTemplate`,`level`,`durationWeeks`,`createdAt` SEPARATOR ''),''),256) signature FROM `workoutplans`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: workoutdays. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=73 AND signature='bb70a05674dc39128cb98df8227f0101e3f31b3ff54f6ea6fb3f0938394a2d4c' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`dayId`,`planId`,`dayName`,`order`,`weekDay`) AS CHAR),256) ORDER BY `dayId`,`planId`,`dayName`,`order`,`weekDay` SEPARATOR ''),''),256) signature FROM `workoutdays`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: exerciseconfigs. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=364 AND signature='fa1ad95d154fc23bae831abc3f42ad48bbd26e513364e3827516b2c9f1414994' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`configId`,`exerciseId`,`dayId`,`sets`,`reps`,`restTime`,`order`) AS CHAR),256) ORDER BY `configId`,`exerciseId`,`dayId`,`sets`,`reps`,`restTime`,`order` SEPARATOR ''),''),256) signature FROM `exerciseconfigs`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: exercises. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=57 AND signature='7d70abb4adfeb4754a85e6982a8259b8082f7211a6b8566bced51cb8310654bf' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`exerciseId`,`name`,`description`,`difficulty`) AS CHAR),256) ORDER BY `exerciseId`,`name`,`description`,`difficulty` SEPARATOR ''),''),256) signature FROM `exercises`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: exercisealternatives. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=64 AND signature='b133bb54a9c8ec927697e8ae91bc2e372476c5d122f68172c4149dbdf236df0c' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`alternativeId`,`exerciseId`,`alternativeExerciseId`,`priority`,`note`) AS CHAR),256) ORDER BY `alternativeId`,`exerciseId`,`alternativeExerciseId`,`priority`,`note` SEPARATOR ''),''),256) signature FROM `exercisealternatives`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: gymuserworkoutplans. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=11 AND signature='91832b8425cb2089f61af749264d16a27444c53c95a78de39df30539567ebf9d' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`profileId`,`planId`,`joinedAt`,`startedAt`,`status`) AS CHAR),256) ORDER BY `profileId`,`planId`,`joinedAt`,`startedAt`,`status` SEPARATOR ''),''),256) signature FROM `gymuserworkoutplans`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: workoutsessions. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=224 AND signature='f219b15207ffb04cbf36b80c2de68c376942bb8af86c96eee7f56b22a1ab0e59' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`workoutSessionId`,`profileId`,`dayId`,`startTime`,`endTime`,`totalDuration`,`status`) AS CHAR),256) ORDER BY `workoutSessionId`,`profileId`,`dayId`,`startTime`,`endTime`,`totalDuration`,`status` SEPARATOR ''),''),256) signature FROM `workoutsessions`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: performedexercises. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=959 AND signature='c332c8e574b54deb06fa468ed43016b03a61f950eaa63a051123d225913efdd0' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`performedExerciseId`,`workoutSessionId`,`exerciseId`,`originalExerciseId`,`isSubstituted`,`isActive`,`isCompleted`) AS CHAR),256) ORDER BY `performedExerciseId`,`workoutSessionId`,`exerciseId`,`originalExerciseId`,`isSubstituted`,`isActive`,`isCompleted` SEPARATOR ''),''),256) signature FROM `performedexercises`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: exercisesets. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=3108 AND signature='d17ea8deb069b4a28e821328ca9f9efc8e222d8f4aabf270b976b50226b49350' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`setId`,`performedExerciseId`,`setNumber`,`weight`,`reps`,`preValue`) AS CHAR),256) ORDER BY `setId`,`performedExerciseId`,`setNumber`,`weight`,`reps`,`preValue` SEPARATOR ''),''),256) signature FROM `exercisesets`) fingerprint)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Baseline changed: bodymetrics. Refresh audit before applying', IF((@seed_apply=0 OR (SELECT n=81 AND signature='5eca76616764e49d36c605315506ead5baec26dcfe63c5194e1740782c24cce9' FROM (SELECT COUNT(*) n, SHA2(COALESCE(GROUP_CONCAT(SHA2(CAST(JSON_ARRAY(`metricId`,`profileId`,`height`,`weight`,`recordedAt`) AS CHAR),256) ORDER BY `metricId`,`profileId`,`height`,`weight`,`recordedAt` SEPARATOR ''),''),256) signature FROM `bodymetrics`) fingerprint)),1,0);

SET @before_accounts=(SELECT COUNT(*) FROM Accounts);
SET @before_users=(SELECT COUNT(*) FROM GymUsers);
-- 1. Accounts and profiles. No old rows are updated.
INSERT INTO Accounts (username,email,password,role,status,createdAt)
SELECT username,email,'GymDemoV2@2026!','GYM_USER',status,createdAt FROM sd_users WHERE @seed_apply=1 ORDER BY no;
SET @added_accounts=ROW_COUNT();
INSERT INTO GymUsers (accountId,fullName,gender,level,goal,sessionsPerWeek,status)
SELECT a.accountId,s.fullName,s.gender,s.level,s.goal,s.sessionsPerWeek,s.profileStatus FROM sd_users s JOIN Accounts a ON a.username=s.username AND a.email=s.email WHERE @seed_apply=1 ORDER BY s.no;
SET @added_profiles=ROW_COUNT();
CREATE TEMPORARY TABLE sd_user_ids ENGINE=InnoDB AS
SELECT a.username AS userKey,a.accountId,g.profileId FROM Accounts a JOIN GymUsers g ON g.accountId=a.accountId WHERE a.accountId=28 OR a.username IN (SELECT username FROM sd_users);
-- 2. Necessary personal schedules: templates lack weekDay. All exercises already exist.
INSERT INTO WorkoutPlans (title,description,creatorId,isTemplate,level,durationWeeks,createdAt)
SELECT s.title,s.description,u.accountId,0,s.level,s.durationWeeks,s.createdAt FROM sd_plans s JOIN sd_user_ids u ON u.userKey=s.userKey WHERE @seed_apply=1 ORDER BY s.planKey;
SET @added_plans=ROW_COUNT();
CREATE TEMPORARY TABLE sd_plan_ids ENGINE=InnoDB AS
SELECT s.planKey,p.planId FROM sd_plans s JOIN sd_user_ids u ON u.userKey=s.userKey JOIN WorkoutPlans p ON p.title=s.title AND p.creatorId=u.accountId AND p.description=s.description
UNION ALL SELECT 'existing_minh_active',p.planId FROM WorkoutPlans p JOIN GymUserWorkoutPlans uw ON uw.planId=p.planId JOIN GymUsers g ON g.profileId=uw.profileId WHERE g.accountId=28 AND p.title='Nguyễn Hoàng Minh - minh_current' AND uw.status='ACTIVE';
INSERT INTO WorkoutDays (planId,dayName,`order`,weekDay)
SELECT p.planId,s.dayName,s.dayOrder,s.weekDay FROM sd_days s JOIN sd_plan_ids p ON p.planKey=s.planKey WHERE @seed_apply=1 AND s.planKey<>'existing_minh_active' ORDER BY s.planKey,s.dayOrder;
SET @added_days=ROW_COUNT();
CREATE TEMPORARY TABLE sd_day_ids ENGINE=InnoDB AS
SELECT p.planKey,d.`order` AS dayOrder,d.dayId FROM sd_plan_ids p JOIN WorkoutDays d ON d.planId=p.planId;
INSERT INTO ExerciseConfigs (exerciseId,dayId,sets,reps,restTime,`order`)
SELECT e.exerciseId,d.dayId,s.sets,s.reps,s.restTime,s.exerciseOrder FROM sd_configs s JOIN sd_day_ids d ON d.planKey=s.planKey AND d.dayOrder=s.dayOrder JOIN Exercises e ON e.name=s.exerciseName WHERE @seed_apply=1 AND s.planKey<>'existing_minh_active' ORDER BY s.planKey,s.dayOrder,s.exerciseOrder;
SET @added_configs=ROW_COUNT();
INSERT INTO GymUserWorkoutPlans (profileId,planId,joinedAt,startedAt,status)
SELECT u.profileId,p.planId,s.joinedAt,s.startedAt,s.status FROM sd_memberships s JOIN sd_user_ids u ON u.userKey=s.userKey JOIN sd_plan_ids p ON p.planKey=s.planKey WHERE @seed_apply=1;
SET @added_memberships=ROW_COUNT();
-- 3. Sessions, performed exercises and sets. Fixed calendar is stable on rerun.
INSERT INTO WorkoutSessions (profileId,dayId,startTime,endTime,totalDuration,status)
SELECT u.profileId,d.dayId,s.startTime,s.endTime,s.totalDuration,s.status FROM sd_sessions s JOIN sd_user_ids u ON u.userKey=s.userKey JOIN sd_day_ids d ON d.planKey=s.planKey AND d.dayOrder=s.dayOrder WHERE @seed_apply=1 ORDER BY s.startTime,s.userKey;
SET @added_sessions=ROW_COUNT();
CREATE TEMPORARY TABLE sd_session_ids ENGINE=InnoDB AS
SELECT s.sessionKey,ws.workoutSessionId FROM sd_sessions s JOIN sd_user_ids u ON u.userKey=s.userKey JOIN sd_day_ids d ON d.planKey=s.planKey AND d.dayOrder=s.dayOrder JOIN WorkoutSessions ws ON ws.profileId=u.profileId AND ws.dayId=d.dayId AND ws.startTime=s.startTime;
INSERT INTO PerformedExercises (workoutSessionId,exerciseId,originalExerciseId,isSubstituted,isActive,isCompleted)
SELECT ws.workoutSessionId,e.exerciseId,o.exerciseId,s.isSubstituted,s.isActive,s.isCompleted FROM sd_performed s JOIN sd_session_ids ws ON ws.sessionKey=s.sessionKey JOIN Exercises e ON e.name=s.exerciseName JOIN Exercises o ON o.name=s.originalExerciseName WHERE @seed_apply=1;
SET @added_performed=ROW_COUNT();
CREATE TEMPORARY TABLE sd_performed_ids ENGINE=InnoDB AS
SELECT s.sessionKey,s.exerciseName,pe.performedExerciseId FROM sd_performed s JOIN sd_session_ids ws ON ws.sessionKey=s.sessionKey JOIN Exercises e ON e.name=s.exerciseName JOIN PerformedExercises pe ON pe.workoutSessionId=ws.workoutSessionId AND pe.exerciseId=e.exerciseId;
INSERT INTO ExerciseSets (performedExerciseId,setNumber,weight,reps,preValue)
SELECT p.performedExerciseId,s.setNumber,s.weight,s.reps,s.preValue FROM sd_sets s JOIN sd_performed_ids p ON p.sessionKey=s.sessionKey AND p.exerciseName=s.exerciseName WHERE @seed_apply=1;
SET @added_sets=ROW_COUNT();
-- 4. Body metrics. Minh's confirmed reference is 60 kg, old measurements stay intact.
INSERT INTO BodyMetrics (profileId,height,weight,recordedAt)
SELECT u.profileId,s.height,s.weight,s.recordedAt FROM sd_metrics s JOIN sd_user_ids u ON u.userKey=s.userKey WHERE @seed_apply=1;
SET @added_metrics=ROW_COUNT();

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: accounts', IF((@added_accounts=@seed_apply*30),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: profiles', IF((@added_profiles=@seed_apply*30),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: plans', IF((@added_plans=@seed_apply*39),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: days', IF((@added_days=@seed_apply*153),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: configs', IF((@added_configs=@seed_apply*783),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: memberships', IF((@added_memberships=@seed_apply*39),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: sessions', IF((@added_sessions=@seed_apply*506),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: performed', IF((@added_performed=@seed_apply*2580),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: sets', IF((@added_sets=@seed_apply*8377),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Exact inserted row count: metrics', IF((@added_metrics=@seed_apply*122),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'All user and plan mappings must be unambiguous', IF(((SELECT COUNT(*) FROM sd_user_ids)=31 AND (SELECT COUNT(*) FROM sd_plan_ids)=40 AND (SELECT COUNT(*) FROM sd_day_ids)=156),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'All seeded sessions and performed exercises still exist exactly once', IF(((SELECT COUNT(*) FROM sd_session_ids)=506 AND (SELECT COUNT(*) FROM sd_performed_ids)=2580),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'All seeded set numbers still exist exactly once', IF(((SELECT COUNT(*) FROM sd_sets s JOIN sd_performed_ids p ON p.sessionKey=s.sessionKey AND p.exerciseName=s.exerciseName JOIN ExerciseSets es ON es.performedExerciseId=p.performedExerciseId AND es.setNumber=s.setNumber)=8377),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'All seeded metric timestamps still exist exactly once', IF(((SELECT COUNT(*) FROM sd_metrics s JOIN sd_user_ids u ON u.userKey=s.userKey JOIN BodyMetrics bm ON bm.profileId=u.profileId AND bm.recordedAt=s.recordedAt)=122),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'At most one active plan for each affected user', IF((NOT EXISTS (SELECT uw.profileId FROM GymUserWorkoutPlans uw JOIN sd_user_ids u ON u.profileId=uw.profileId WHERE uw.status='ACTIVE' GROUP BY uw.profileId HAVING COUNT(*)>1)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Minh total is 51 on first application', IF((@seed_apply=0 OR (SELECT COUNT(*) FROM WorkoutSessions ws JOIN GymUsers g ON g.profileId=ws.profileId WHERE g.accountId=28)=51),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Seed session calendar and membership valid', IF((@seed_apply=0 OR NOT EXISTS (SELECT 1 FROM sd_session_ids m JOIN WorkoutSessions ws ON ws.workoutSessionId=m.workoutSessionId JOIN WorkoutDays wd ON wd.dayId=ws.dayId JOIN GymUsers g ON g.profileId=ws.profileId JOIN Accounts a ON a.accountId=g.accountId LEFT JOIN GymUserWorkoutPlans uw ON uw.profileId=g.profileId AND uw.planId=wd.planId WHERE uw.profileId IS NULL OR ws.startTime<a.createdAt OR ws.startTime<uw.joinedAt OR DATE(ws.startTime)<uw.startedAt OR WEEKDAY(ws.startTime)+1<>wd.weekDay OR ws.endTime>NOW() OR ws.totalDuration<>TIMESTAMPDIFF(MINUTE,ws.startTime,ws.endTime))),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'New sessions do not overlap any session', IF((@seed_apply=0 OR NOT EXISTS (SELECT 1 FROM sd_session_ids m JOIN WorkoutSessions a ON a.workoutSessionId=m.workoutSessionId JOIN WorkoutSessions b ON a.profileId=b.profileId AND a.workoutSessionId<>b.workoutSessionId AND a.startTime<COALESCE(b.endTime,NOW()) AND b.startTime<a.endTime)),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'Seed performed exercises match the actual day configuration', IF((@seed_apply=0 OR NOT EXISTS (SELECT 1 FROM sd_performed_ids m JOIN PerformedExercises pe ON pe.performedExerciseId=m.performedExerciseId JOIN WorkoutSessions ws ON ws.workoutSessionId=pe.workoutSessionId WHERE pe.isActive<>1 OR pe.isCompleted<>1 OR pe.isSubstituted<>0 OR pe.originalExerciseId<>pe.exerciseId OR NOT EXISTS (SELECT 1 FROM ExerciseConfigs c WHERE c.dayId=ws.dayId AND c.exerciseId=pe.exerciseId))),1,0);

INSERT INTO sd_guard (message, ok) SELECT 'New metric values and timestamps valid', IF((@seed_apply=0 OR NOT EXISTS (SELECT 1 FROM sd_metrics m JOIN sd_user_ids u ON u.userKey=m.userKey JOIN Accounts a ON a.accountId=u.accountId WHERE m.recordedAt<a.createdAt OR m.recordedAt>NOW() OR m.height<=0 OR m.weight<=0)),1,0);

-- Counts are selected before COMMIT so the runner can report exact mutations.
SELECT @seed_apply AS applied, @before_accounts AS accountsBefore, (SELECT COUNT(*) FROM Accounts) AS accountsAfter, @before_users AS profilesBefore, (SELECT COUNT(*) FROM GymUsers) AS profilesAfter, @added_accounts AS added_accounts, @added_profiles AS added_profiles, @added_plans AS added_plans, @added_days AS added_days, @added_configs AS added_configs, @added_memberships AS added_memberships, @added_sessions AS added_sessions, @added_performed AS added_performed, @added_sets AS added_sets, @added_metrics AS added_metrics;
COMMIT;
SELECT RELEASE_LOCK('QuanLyLichTapGym.sample_seed_v2') AS released;
-- Temporary tables are released when this dedicated connection closes.
